import { Component, Output, EventEmitter, Input, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatIconModule } from '@angular/material/icon';

@Component({
  selector: 'app-image-upload',
  standalone: true,
  imports: [CommonModule, MatIconModule],
  templateUrl: './image-upload.component.html',
  styleUrls: ['./image-upload.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ImageUploadComponent {
  @Input() recommendedSize = '1200 x 630px (16:9)';
  @Input() maxFileSizeMB = 5;
  @Output() imageSelected = new EventEmitter<{ file: File; previewUrl: string }>();
  @Output() imageRemoved = new EventEmitter<void>();

  previewUrl: string | null = null;
  fileName: string | null = null;
  isDragging = false;
  isPortrait = false;
  cropTop = 0; // percentage from top for portrait crop
  error: string | null = null;

  allowedExtensions = ['JPG', 'JPEG', 'PNG', 'GIF', 'WebP'];
  allowedMimeTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];

  constructor(private cdr: ChangeDetectorRef) {}

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    this.isDragging = true;
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    this.isDragging = false;
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    this.isDragging = false;
    const files = event.dataTransfer?.files;
    if (files && files.length > 0) {
      this.processFile(files[0]);
    }
  }

  onFileSelect(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      this.processFile(input.files[0]);
      input.value = ''; // reset so same file can be selected again
    }
  }

  private processFile(file: File): void {
    this.error = null;
    // Check mime type
    if (!this.allowedMimeTypes.includes(file.type)) {
      this.error = `対応していないファイル形式です。${this.allowedExtensions.join(', ')} のみ対応しています。`;
      this.cdr.markForCheck();
      return;
    }
    // Check file size
    if (file.size > this.maxFileSizeMB * 1024 * 1024) {
      this.error = `ファイルサイズが${this.maxFileSizeMB}MBを超えています。`;
      this.cdr.markForCheck();
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const url = e.target?.result as string;
      // Check if portrait
      const img = new Image();
      img.onload = () => {
        this.isPortrait = img.height > img.width * 1.3;
        this.cropTop = 0;
        this.previewUrl = url;
        this.fileName = file.name;
        this.imageSelected.emit({ file, previewUrl: url });
        this.cdr.markForCheck();
      };
      img.src = url;
    };
    reader.readAsDataURL(file);
  }

  onCropMove(event: MouseEvent, container: HTMLElement): void {
    if (!this.isPortrait) return;
    const rect = container.getBoundingClientRect();
    const y = event.clientY - rect.top;
    const percent = Math.max(0, Math.min(100, (y / rect.height) * 100));
    this.cropTop = percent;
  }

  removeImage(): void {
    this.previewUrl = null;
    this.fileName = null;
    this.isPortrait = false;
    this.cropTop = 0;
    this.error = null;
    this.imageRemoved.emit();
  }
}
